"""mnist_cnn - generated by AI Made Easy."""
import torch
import torch.nn as nn


class MnistCnn(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv2d_1 = nn.Conv2d(in_channels=1, out_channels=16, kernel_size=3, stride=1, padding=1, dilation=1)
        self.relu_1 = nn.ReLU()
        self.maxpool2d_1 = nn.MaxPool2d(kernel_size=2, stride=2, padding=0)
        self.conv2d_2 = nn.Conv2d(in_channels=16, out_channels=32, kernel_size=3, stride=1, padding=1, dilation=1)
        self.relu_2 = nn.ReLU()
        self.dense_1 = nn.Linear(in_features=32, out_features=10, bias=True)

    def forward(self, x):
        v_conv2d_1 = self.conv2d_1(x)
        v_relu_1 = self.relu_1(v_conv2d_1)
        v_maxpool2d_1 = self.maxpool2d_1(v_relu_1)
        v_conv2d_2 = self.conv2d_2(v_maxpool2d_1)
        v_relu_2 = self.relu_2(v_conv2d_2)
        v_global_avgpool2d_1 = torch.mean(v_relu_2, dim=(2, 3))
        v_dense_1 = self.dense_1(v_global_avgpool2d_1)
        return v_dense_1


if __name__ == "__main__":
    model = MnistCnn()
    print(model)
    x = torch.randn(1, 1, 28, 28)
    out = model(x)
    print("input shape: ", tuple(x.shape))
    print("output shape:", tuple(out.shape))
